#!/bin/bash
# tools:
#   llvm-profdata: 21.1.4
#        llvm-cov: 21.1.4
#         genhtml: 1.16
set -e

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "$SCRIPT_DIR"

# start coverage from only profiles generated by this test run
rm -f *.profraw baz.profdata

if [[ "${1:-}" != "nobuild" && "${SKIP_BUILD:-0}" != 1 ]]; then
    ../../make.sh build prof asan
fi

BIN="../../baz"
MACHINE="${MACHINE:-x86_64}"
OPTS="--vars=262144 --checks=upper,lower,line --reproduce-source"

rm -f gen.s out err

SEP="--------------------------------------------------------------------------------"
echo $SEP
echo "running: $BIN --target=$MACHINE $OPTS"
echo $SEP

export UBSAN_OPTIONS="print_stacktrace=1"
export ASAN_OPTIONS="fast_unwind_on_fatal=0:print_stacktrace=1:detect_stack_use_after_return=1:check_initialization_order=1:strict_init_order=1:detect_leaks=1:halt_on_error=1:external_symbolizer=1"
export ASAN_SYMBOLIZER_PATH="$(which llvm-symbolizer)"
export ASAN_SYMBOLIZE=1

# Common: compile and assemble
assemble_and_link() {
    case "$MACHINE" in
        x86_64)
            nasm -f elf64 gen.s
            ld -s -T ../../baz.ld -o gen gen.o
            ;;
        rv32i)
            llvm-mc -triple=riscv32 -mattr=-m,-a,-f,-d,-c -filetype=obj gen.s -o gen.o
            ld.lld -m elf32lriscv -e _start -o gen gen.o
            ;;
    esac
}

execute_program() {
    case "$MACHINE" in
        x86_64) ./gen ;;
        rv32i) qemu-riscv32 ./gen ;;
    esac
}

compile_and_build() {
    LLVM_PROFILE_FILE="${SRC%.*}.profraw" $BIN "$SRC.baz" --target="$MACHINE" $OPTS 2>err >gen.s
    if [ $? -ne 0 ]; then
        echo "compiler failed. see 'err' and 'gen.s'" >&2
        exit 1
    fi
    assemble_and_link
}

compile_and_build_no_checks() {
    LLVM_PROFILE_FILE="${SRC%.*}.profraw" $BIN "$SRC.baz" --target="$MACHINE" --reproduce-source 2>err >gen.s
    if [ $? -ne 0 ]; then
        echo "compiler failed. see 'err' and 'gen.s'" >&2
        exit 1
    fi
    assemble_and_link
}

compile_and_build_with_opts() {
    local opts="$1"
    LLVM_PROFILE_FILE="${SRC%.*}.profraw" $BIN "$SRC.baz" --target="$MACHINE" $opts --reproduce-source 2>err >gen.s
    if [ $? -ne 0 ]; then
        echo "compiler failed. see 'err' and 'gen.s'" >&2
        exit 1
    fi
    assemble_and_link
}

# Common: compile and assemble
compile_expect_error() {
    set +e
    LLVM_PROFILE_FILE="${SRC%.*}.profraw" $BIN "$SRC.baz" --target="$MACHINE" $OPTS 2>out
    local exit_code=$?
    set -e
    if [[ $exit_code -ne 1 ]]; then
        echo "FAILED. expected compiler exit 1 got $exit_code"
        exit 1
    fi
}

# Common: compare output with expected
check_output() {
    local expected="$1"
    if cmp -s out "$expected"; then
        echo ok
    else
        echo "FAILED. output differs. see: diff out $expected"
        exit 1
    fi
}

# Test with exit code
RUN() {
    echo -n "$SRC: "
    compile_and_build

    set +e
    execute_program 2>err
    local exit_code=$?
    set -e

    if [ $exit_code -eq $EXP ]; then
        echo ok
    else
        echo "FAILED. expected $EXP got $exit_code"
        exit 1
    fi
}

RUN_ERR() {
    echo -n "$SRC: "
    compile_and_build

    set +e
    execute_program 2>out
    local exit_code=$?
    set -e

    if [ $exit_code -ne $EXP ]; then
        echo "FAILED. expected $EXP got $exit_code"
        exit 1
    fi

    check_output "${SRC%.*}.out"
}

RUN_ERR_OPTS() {
    echo -n "$SRC: "
    compile_and_build_with_opts "$1"

    set +e
    execute_program 2>out
    local exit_code=$?
    set -e

    if [ $exit_code -ne $EXP ]; then
        echo "FAILED. expected $EXP got $exit_code"
        exit 1
    fi

    check_output "${SRC%.*}.out"
}

RUN_NO_CHECKS() {
    echo -n "$SRC: "
    compile_and_build_no_checks

    set +e
    execute_program 2>err
    local exit_code=$?
    set -e

    if [ $exit_code -eq $EXP ]; then
        echo ok
    else
        echo "FAILED. expected $EXP got $exit_code"
        exit 1
    fi
}

# Test with output comparison (no input)
DIFF() {
    echo -n "$SRC: "
    compile_and_build
    execute_program >out
    check_output "${SRC%.*}.out"
}

# Test with input file
DIFFINP() {
    echo -n "$SRC: "
    compile_and_build
    execute_program <"${SRC%.*}.in" >out
    check_output "${SRC%.*}.out"
}

# Test with line-by-line input
DIFFINP2() {
    echo -n "$SRC: "
    compile_and_build

    while read -r line; do
        echo "$line"
        sleep 0.001 # Small wait for single line to be received by `read`
    done <"${SRC%.*}.in" | execute_program >out

    check_output "${SRC%.*}.out"
}

# Test with Python script
DIFFPY() {
    echo -n "$SRC: "
    compile_and_build
    "./${SRC%.*}.py" >out
    check_output "${SRC%.*}.out"
}

# Test with output comparison of compiler (no input)
COMPERR() {
    echo -n "$SRC: "
    compile_expect_error
    check_output "${SRC%.*}.out"
}

# Run all test cases
source "$SCRIPT_DIR/run-tests-cases.sh"

# Cleanup
rm -f gen gen.o gen.s diff.baz out err

echo $SEP

if [[ "$1" == "nobuild" ]]; then
    exit 0
fi

# Process coverage data
llvm-profdata merge -o baz.profdata -sparse $(ls *.profraw)
llvm-cov show -format=html -output-dir=report/ -instr-profile=baz.profdata -object=$BIN

echo "coverage report generated in $(realpath "report/")"
echo $SEP
